// M3 — DOCKER launcher (the first REAL launcher; OOB only, never on the data path).
//
// The docker launcher starts a containerized agent with `docker run -d`,
// injecting the bootstrap env the agent needs to dial back in and register
// (host-v2-design.md §M3 + §4): `GINO_HOST_URL`, the shared
// `GINO_REGISTER_TOKEN` (no longer one-time), and a per-launch
// correlation nonce `GINO_LAUNCH_NONCE` (generated by `control.launchAgent`
// and passed through `req.env`). It also points the engine at the host's
// credential proxy via `ANTHROPIC_BASE_URL`/`OPENAI_BASE_URL = <hostUrl>/llm`
// (M7) so the agent never holds upstream LLM creds.
//
// `ref` is the container id; `stop`/`restart`/`remove`/`inspect` shell out to
// the docker CLI keyed by that id. Every shell-out goes through the injectable
// `spawn` seam — tests mock it, so NO real docker is required (and the binary is
// never touched at import time; only on an actual op).
import type { InspectState, Launcher, LaunchRequest, LaunchResult } from "./types";

/** Result of a shelled-out command — the surface the `spawn` seam returns. */
export interface SpawnResult {
  readonly exitCode: number;
  readonly stdout: string;
  readonly stderr: string;
}

/**
 * Options handed through the `spawn` seam. `signal` aborts (kills) the child —
 * the launcher fires it on the per-op deadline. `env` is EXTRA
 * child environment — the injected `spawn` merges it over the process env —
 * secrets ride here instead of the argv.
 */
export interface SpawnOptions {
  readonly signal?: AbortSignal;
  readonly env?: Record<string, string>;
}

/** The single shell-out seam. The app injects its process-spawn adapter; tests inject a fake. */
export type SpawnFn = (cmd: readonly string[], opts?: SpawnOptions) => Promise<SpawnResult>;

/**
 * Thrown when a docker CLI call exceeds the per-op deadline. The
 * child is killed; callers (the M3 control layer) can catch this DISTINCT
 * error and degrade — e.g. fall back to a WS `close` — instead of hanging on
 * a wedged docker daemon.
 */
export class DockerOpTimeoutError extends Error {
  constructor(op: string, timeoutMs: number) {
    super(`docker ${op} timed out after ${timeoutMs}ms`);
    this.name = "DockerOpTimeoutError";
  }
}

/** Default per-op deadline. Overridable via `DockerLauncherOptions.opTimeoutMs`. */
export const DEFAULT_DOCKER_OP_TIMEOUT_MS = 30_000;

/**
 * Construction options. The docker binary, default image and extra `docker run`
 * flags are configurable — so deployments can point at `podman`/a custom path —
 * and the shell-out seam is REQUIRED: core never spawns a process itself; the
 * app supplies its process-spawn adapter and tests a recording `spawn`. None of
 * this requires docker to be present until an op actually runs.
 */
export interface DockerLauncherOptions {
  /** The docker binary name or path. Default `"docker"`. */
  readonly docker?: string;
  /** Default image to run when a launch request carries no `resources.image`. */
  readonly image?: string;
  /** Extra flags inserted into `docker run` (after the injected `-e` env). */
  readonly runArgs?: readonly string[];
  /** Shell-out seam (required). The app injects its process-spawn adapter; tests inject a fake. */
  readonly spawn: SpawnFn;
  /** Per-op deadline in ms. Default `DEFAULT_DOCKER_OP_TIMEOUT_MS`. */
  readonly opTimeoutMs?: number;
}

/** The launcher `kind` selected by `agents.launcher_kind = "docker"`. */
export const DOCKER_LAUNCHER_KIND = "docker" as const;

const RE_TRAILING_SLASH = /\/+$/;

/**
 * Build a docker launcher over an injectable `spawn` seam. Capabilities are all
 * `true` — docker can launch a runtime and OOB-control it — so the M3 control
 * layer delegates stop/restart/remove/inspect here (keyed by the container id
 * in `agents.launch_ref`) instead of falling back to a WS `close`.
 */
export function createDockerLauncher(opts: DockerLauncherOptions): Launcher {
  const docker = opts.docker ?? "docker";
  const spawn = opts.spawn;
  const runArgs = opts.runArgs ?? [];
  const defaultImage = opts.image;
  const opTimeoutMs = opts.opTimeoutMs ?? DEFAULT_DOCKER_OP_TIMEOUT_MS;

  /**
   * Shell out with the per-op deadline: the abort signal kills
   * the child, and the op rejects with the distinct `DockerOpTimeoutError` —
   * even if the injected `spawn` ignores the signal — so a wedged docker
   * daemon can never hang an admin control op forever.
   */
  async function spawnWithDeadline(args: readonly string[], env?: Record<string, string>): Promise<SpawnResult> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), opTimeoutMs);
    try {
      return await Promise.race([
        spawn([docker, ...args], { signal: controller.signal, ...(env ? { env } : {}) }),
        new Promise<never>((_, reject) => {
          controller.signal.addEventListener(
            "abort",
            () => reject(new DockerOpTimeoutError(args[0] ?? "op", opTimeoutMs)),
            { once: true },
          );
        }),
      ]);
    }
    finally {
      clearTimeout(timer);
    }
  }

  /** Run a docker subcommand, throwing on a non-zero exit (caller handles inspect's soft path). */
  async function run(args: readonly string[], env?: Record<string, string>): Promise<SpawnResult> {
    const res = await spawnWithDeadline(args, env);
    if (res.exitCode !== 0) {
      const detail = res.stderr.trim() || res.stdout.trim();
      throw new Error(`docker ${args[0]} failed (exit ${res.exitCode})${detail ? `: ${detail}` : ""}`);
    }
    return res;
  }

  return {
    kind: DOCKER_LAUNCHER_KIND,
    capabilities: { canLaunch: true, canStop: true, canRestart: true, canInspect: true },

    // `docker run -d` with the injected bootstrap env; `ref` = the container id
    // printed on stdout. The image comes from `resources.image` (per-launch
    // override) falling back to the constructor default.
    async launch(req: LaunchRequest): Promise<LaunchResult> {
      const reqImage = typeof req.resources?.image === "string" ? req.resources.image : undefined;
      const image = reqImage ?? defaultImage;
      if (!image) {
        throw new Error("docker launcher: no image (set DockerLauncherOptions.image or req.resources.image)");
      }

      // The caller's `req.env` (carrying the per-launch GINO_LAUNCH_NONCE,
      // plus any extras) goes in FIRST; the host-authoritative connection keys
      // are spread LAST so they can never be clobbered by caller-supplied env.
      const llmBase = `${req.hostUrl.replace(RE_TRAILING_SLASH, "")}/llm`;
      const env: Record<string, string> = {
        ...(req.env ?? {}),
        GINO_HOST_URL: req.hostUrl,
        GINO_REGISTER_TOKEN: req.registerToken,
        ANTHROPIC_BASE_URL: llmBase,
        OPENAI_BASE_URL: llmBase,
      };
      // Value-less `-e KEY` — docker inherits each value from the
      // CLI process env (supplied via the spawn seam's `env`), so no secret
      // (the register token above all) ever appears on the docker argv, where
      // it would be world-readable via /proc/<pid>/cmdline.
      const envArgs = Object.keys(env).flatMap(k => ["-e", k]);

      const res = await run(["run", "-d", ...envArgs, ...runArgs, image], env);
      const ref = res.stdout.trim();
      if (!ref) {
        throw new Error("docker run -d returned no container id");
      }
      return { ref };
    },

    async stop(ref: string): Promise<void> {
      await run(["stop", ref]);
    },

    async restart(ref: string): Promise<void> {
      await run(["restart", ref]);
    },

    // Force-remove: a stopped or running container is torn down (the control
    // layer gates this on `canStop`, so it is only reached for a docker agent).
    async remove(ref: string): Promise<void> {
      await run(["rm", "-f", ref]);
    },

    // Coarse runtime state from `docker inspect`. A docker error (e.g. the
    // container is gone) — or a per-op timeout — maps to `unknown` rather than
    // throwing — the control layer treats `inspect` as best-effort observation.
    async inspect(ref: string): Promise<InspectState> {
      let res: SpawnResult;
      try {
        res = await spawnWithDeadline(["inspect", "-f", "{{.State.Status}}", ref]);
      }
      catch {
        return "unknown";
      }
      if (res.exitCode !== 0) {
        return "unknown";
      }
      const state = res.stdout.trim();
      if (state === "running") {
        return "running";
      }
      if (state === "exited" || state === "dead") {
        return "exited";
      }
      return "unknown";
    },
  };
}
